using namespace std;

using ll = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    ll K;
    cin >> N >> K;

    string S;
    cin >> S;

    vector<array<int, 26>> nextPos(N + 1);
    nextPos[N].fill(N);

    for (int i = N - 1; i >= 0; --i) {
        nextPos[i] = nextPos[i + 1];
        nextPos[i][S[i] - 'a'] = i;
    }

    vector<vector<ll>> dp(N + 1, vector<ll>(N + 1));
    for (int i = N; i >= 0; --i) {
        dp[i][0] = 1;
        for (int len = 1; len <= N - i; ++len) {
            __int128 count = 0;
            for (int c = 0; c < 26; ++c) {
                int pos = nextPos[i][c];
                if (pos < N) {
                    count += dp[pos + 1][len - 1];
                    if (count >= K) {
                        count = K;
                        break;
                    }
                }
            }
            dp[i][len] = static_cast<ll>(count);
        }
    }

    ll answer = 0;
    for (int len = N; len >= 0 && K > 0; --len) {
        ll take = min(K, dp[0][len]);
        answer += take * (N - len);
        K -= take;
    }

    cout << (K == 0 ? answer : -1) << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using ll = long long;
using i128 = __int128_t;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    ll K;
    cin >> N >> K;

    string S;
    cin >> S;

    vector<vector<i128>> dp(N + 1, vector<i128>(N + 1));
    vector<int> last(256, -1);
    dp[0][0] = 1;

    for (int i = 1; i <= N; ++i) {
        dp[i][0] = 1;
        unsigned char c = S[i - 1];

        for (int len = 1; len <= i; ++len) {
            dp[i][len] = dp[i - 1][len] + dp[i - 1][len - 1];
            if (last[c] != -1) {
                dp[i][len] -= dp[last[c]][len - 1];
            }
        }
        last[c] = i - 1;
    }

    ll answer = 0;
    ll remaining = K;

    for (int len = N; len >= 0 && remaining > 0; --len) {
        ll take = remaining;
        if (dp[N][len] < static_cast<i128>(remaining)) {
            take = static_cast<ll>(dp[N][len]);
        }

        answer += take * (N - len);
        remaining -= take;
    }

    cout << (remaining == 0 ? answer : -1) << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using ll = long long;

ll solve() {
    int N;
    ll K;
    cin >> N >> K;

    string S;
    cin >> S;

    vector<array<int, 256>> nextPos(N + 1);
    nextPos[N].fill(-1);

    for (int i = N - 1; i >= 0; --i) {
        nextPos[i] = nextPos[i + 1];
        nextPos[i][static_cast<unsigned char>(S[i])] = i;
    }

    vector<vector<ll>> dp(N + 1, vector<ll>(N + 1, 0));

    for (int pos = N; pos >= 0; --pos) {
        dp[pos][0] = min(1LL, K);

        for (int len = 1; len <= N - pos; ++len) {
            ll count = 0;

            for (int c = 0; c < 256; ++c) {
                int index = nextPos[pos][c];
                if (index == -1) continue;

                ll add = dp[index + 1][len - 1];
                if (count >= K - add) {
                    count = K;
                    break;
                }
                count += add;
            }

            dp[pos][len] = count;
        }
    }

    ll answer = 0;

    for (int len = N; len >= 0 && K > 0; --len) {
        ll take = min(K, dp[0][len]);
        answer += take * (N - len);
        K -= take;
    }

    return K == 0 ? answer : -1;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cout << solve() << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using ll = long long;

ll solve() {
    int N, K;
    cin >> N >> K;

    string S;
    cin >> S;

    if (K == 0) return 0;

    queue<string> q;
    unordered_set<string> seen;

    q.push(S);
    seen.insert(S);

    ll answer = 0;

    while (!q.empty() && static_cast<int>(seen.size()) < K) {
        string current = q.front();
        q.pop();

        for (int i = 0; i < static_cast<int>(current.size()); ++i) {
            string next = current.substr(0, i) + current.substr(i + 1);

            if (seen.insert(next).second) {
                answer += N - static_cast<int>(next.size());
                q.push(next);

                if (static_cast<int>(seen.size()) == K) break;
            }
        }
    }

    return static_cast<int>(seen.size()) >= K ? answer : -1;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cout << solve() << '\n';
    return 0;
}

