    int N;
    ll K;
    cin >> N >> K;

    string S;
    cin >> S;

    vector<array<ll, 26>> ending(N + 1);
    vector<ll> count(N + 1, 0);
    count[0] = 1;

    for (int i = 0; i < N; ++i) {
        int c = S[i] - 'a';

        for (int len = i + 1; len >= 1; --len) {
            ending[len][c] = count[len - 1];

            ll sum = 0;
            for (ll value : ending[len]) {
                if (sum >= K - value) {
                    sum = K;
                    break;
                }
                sum += value;
            }
            count[len] = sum;
        }
    }

    ll answer = 0;
    for (int len = N; len >= 0 && K > 0; --len) {
        ll take = min(K, count[len]);
        answer += take * (N - len);
        K -= take;
    }

    return K == 0 ? answer : -1;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cout << solve() << '\n';
    return 0;
}

